const safety = `<div class="notice"><strong>Use safely:</strong> Follow these steps only for a router or network you own or are authorised to manage. Never send Router Portal a router password, Wi-Fi key, MAC address, serial number or private screenshot.</div>`;
const sourceCard = (sources) => `<div class="evidence-card"><div class="evidence-head"><strong>Evidence and scope</strong><span class="status-pill success">SOURCE-BACKED · CHECK DATE</span></div><div class="evidence-grid"><div><small>Sources</small><strong>${sources.length} official references</strong></div><div><small>Scope</small><strong>Model/OS/network dependent</strong></div><div><small>Credentials</small><strong>Never universal</strong></div><div><small>Review</small><strong>Recheck after UI changes</strong></div></div></div>`;
const table = (rows) => `<div class="table-wrap"><table><thead><tr><th>Check</th><th>What it tells you</th><th>Safe next action</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div>`;
const linkList = (links, pageUrl) => links.map(([href,label])=>`<a href="${pageUrl(href)}">${label}</a>`).join(' · ');
const makeBody = (p, pageUrl) => `${safety}${sourceCard(p.sources)}<div class="answer-lead"><strong>Quick answer:</strong> ${p.answer}</div><h2>What this page covers</h2><p>${p.coverage}</p><h2>Step-by-step workflow</h2><ol>${p.steps.map(x=>`<li>${x}</li>`).join('')}</ol><h2>Decision table</h2>${table(p.rows)}<h2>Limits and verification</h2><p>${p.limits}</p><h2>Official sources</h2><ul>${p.sources.map(s=>`<li><a href="${s.url}" rel="noopener">${s.name}</a> <span>(${s.note})</span></li>`).join('')}</ul><h2>Related Router Portal guides</h2><p>${linkList(p.related,pageUrl)}</p><p><strong>Editorial note:</strong> This pilot page is written for one distinct question. Firmware, operating-system menus, ISP policies and regional radio rules can change, so confirm the source and exact device before applying a setting.</p>`;
