 linksys:{name:'Linksys — Atlas Pro 6 support',url:'https://support.linksys.com/kb/article/587-en/?section_id=57',note:'model support workflow'},
 eero:{name:'Amazon eero — eero 6+ support',url:'https://eero.com/support/articles/eero-6-plus',note:'gateway/extender behavior'}
