const R={login:['/router-login/','Router login guide'],ip:['/find-router-ip/','Find the current gateway'],problem:['/router-login-not-working/','Router login troubleshooting'],security:['/security/router-admin-security/','Router security guide'],wifi:['/wifi/wi-fi-7-explained/','Wi-Fi guide'],tools:['/tools/cidr-subnet-calculator/','Subnet calculator'],reset:['/factory-reset-router/','Factory reset warnings']};
const raw=[
['/network/dhcp-server-not-responding/','DHCP Server Not Responding: Find the Broken Link','DHCP server not responding','DHCP failure can be local to one client, a VLAN, the router service or the upstream network. Compare the client state and DHCP server identity before resetting anything.','Use the client’s current address, DHCP-server field and a controlled wired/Wi-Fi comparison to isolate the failing segment.', ['Check whether one or every device is affected.','Inspect IP, mask, gateway and DHCP-server fields on the affected device.','Swap only one variable: cable, port, band or authorised access point.','Restart the DHCP service or router only after recording the current topology.'],[['169.254.x.x','The client did not receive a normal lease','Check link, VLAN and DHCP scope'],['One device only','Client adapter or profile may be involved','Forget/rejoin or renew on that device'],['All clients','Router, uplink or provider handoff may be involved','Check router status before reset']], [S.rfc2131,S.msNet], 'A DHCP timeout does not prove that the router is dead. A guest network, VLAN, bridge mode, exhausted pool or second router can produce a similar symptom.', [R.ip,R.problem,R.tools]],
['/network/169-254-apipa-address/','169.254 IP Address: What APIPA Means and What to Check','169.254 IP address router','An address in 169.254.0.0/16 is commonly a link-local fallback when a device cannot obtain its expected configuration. It is not proof that 192.168.1.1 is your router.', 'Separate physical link, DHCP reachability and manual/static configuration before changing the router.', ['Confirm the active adapter is the one connected to the intended network.','Check link status and cable or Wi-Fi association.','Renew the lease using the platform’s documented command.','Compare with another authorised client on the same segment.'],[['One client has 169.254','Device-side issue is more likely','Recheck adapter and profile'],['All clients have it','DHCP or network path is likely','Check router LAN/DHCP service'],['Static configuration present','APIPA may be a fallback or stale profile','Restore the intended documented mode']], [S.rfc2131,S.msNet], 'Do not infer a router address from an APIPA result. The correct next step is to identify the network path and DHCP source.', [R.ip,R.problem]],
['/network/dhcp-ip-address-conflict/','DHCP IP Address Conflict: Diagnose Duplicate Addresses','DHCP IP address conflict','An address conflict can arise from a second DHCP server, a manually assigned address inside the pool, stale reservations or a device returning from sleep.', 'Record the duplicate symptom and locate the address authority before changing pool settings.', ['Record the conflicting address and affected interfaces without publishing it.','Check whether a second router, extender or hotspot is connected.','Compare DHCP reservations with manually configured clients.','Move one conflicting device to a documented automatic profile and retest.'],[['Two devices report same IP','Duplicate assignment or manual override','Inspect reservation and static settings'],['New router added','Two DHCP authorities may exist','Use one intended LAN authority'],['Conflict after sleep','Lease or resume state may be stale','Renew and verify the lease']], [S.rfc2131,S.cisa], 'MAC addresses and private IPs are sensitive operational data. Keep evidence private and avoid assuming malicious activity from one conflict.', [R.ip,R.security]],
['/network/dhcp-lease-renewal-fails/','DHCP Lease Renewal Fails: Why Connection Drops Later','DHCP lease renewal fails','A connection that works initially but drops during renewal can point to lease timing, a sleeping client, a changing VLAN, a firewall rule or an unstable DHCP service.', 'Compare the time of failure with lease details and test another client on the same network.', ['Note the approximate failure time and interface.','Inspect lease obtained, expiry and DHCP-server fields.','Compare wired and Wi-Fi clients if both are available.','Review router logs only after redacting private identifiers.'],[['All clients renew poorly','DHCP service or upstream path','Check router and provider status'],['One client only','Adapter, driver or sleep behavior','Update or reset only that profile'],['Network changes at renewal','VLAN/bridge or roaming transition','Review topology and logs']], [S.rfc2131,S.msNet], 'Lease durations and UI labels differ by router. Do not publish a universal lease time as a fix.', [R.problem,R.security]],
['/network/multiple-dhcp-servers-home-network/','Multiple DHCP Servers at Home: Detect the Wrong Authority','multiple DHCP servers home network','Two active DHCP servers can hand out different gateways or DNS settings, making only some devices fail.', 'Compare DHCP-server and gateway fields from two clients, then isolate the unauthorised router or extender.', ['Capture configuration fields from two affected clients privately.','Identify every router, access point, extender and hotspot attached by Ethernet.','Disconnect one suspected device at a time from the LAN.','Keep the intended DHCP authority and retest new leases.'],[['Different gateways','Clients are receiving different offers','Find the second DHCP source'],['Different DNS servers','DHCP scopes or policy differ','Compare router LAN settings'],['Only guest devices fail','Intentional isolation may be involved','Check the guest network design']], [S.rfc2131,S.cisa], 'Do not disable a provider-managed gateway without understanding bridge, voice, TV or support dependencies.', [R.ip,R.security]],
['/network/dns-works-intermittently/','Intermittent DNS Failure: Separate Resolver Timeouts from Wi-Fi Drops','intermittent DNS failure','If some names resolve and others time out, compare DNS responses with direct gateway and IP connectivity tests.', 'Run repeatable, local diagnostics and do not treat changing DNS providers as a universal fix.', ['Test the gateway, a known IP and a hostname separately.','Use nslookup or dig against the configured resolver.','Compare wired/Wi-Fi and one alternate authorised client.','Record timeout, SERVFAIL, NXDOMAIN or refusal results.'],[['IP works, name fails','Resolution path is the likely branch','Inspect resolver and cache'],['Only some names fail','Authoritative or policy issue may exist','Compare response codes'],['Everything drops','DNS may be a symptom, not the cause','Check link and gateway']], [S.msDns,S.rfc8415], 'A public DNS change can hide a local DHCP or security problem. Preserve the original configuration and verify the cause.', [R.problem,R.ip]],
['/network/dns-nxdomain-servfail-timeout/','DNS NXDOMAIN vs SERVFAIL vs Timeout: Read the Result','DNS NXDOMAIN SERVFAIL timeout','The response code changes what the resolver is telling you: a name may not exist, the resolver may be unable to complete the query, or the path may be silent.', 'Interpret the response code with the queried name, server and time—not from a browser error alone.', ['Repeat the query against the configured resolver.','Check the exact hostname and search suffix.','Compare an authoritative or documented alternate resolver only for diagnosis.','Keep the output private if it contains internal names.'],[['NXDOMAIN','The queried name was reported as nonexistent','Check spelling and DNS zone'],['SERVFAIL','Resolver could not complete the query','Inspect upstream/validation path'],['Timeout','No timely response was received','Check firewall, path and server load']], [S.msDns,S.rfc2131], 'A single response cannot prove an outage or attack. DNS records and caches change over time.', [R.problem,R.security]],
['/network/double-nat-home-network/','Double NAT at Home: Identify the Two Routing Layers','double NAT home network','Double NAT occurs when a personal router is routed behind another gateway instead of using a documented bridge, passthrough or access-point design.', 'Identify the WAN address on the downstream router and the upstream topology before changing mode.', ['Record the downstream router WAN and LAN ranges privately.','Check whether its WAN address is private or otherwise upstream-managed.','Find the upstream gateway model and supported topology.','Choose bridge/IP passthrough/AP mode only from current documentation.'],[['Downstream WAN is private','Another routing layer is present','Map the upstream gateway'],['Port forwarding fails','Rules may need a second layer or another design','Prefer VPN/relay where suitable'],['Voice/TV breaks after bridge','Provider features may depend on gateway routing','Restore or consult the provider']], [S.rfc7857,S.cisa,S.xfinity], 'Double NAT is not automatically unsafe or broken. The correct architecture depends on ISP features, IPv6, support and the service being used.', [R.problem,R.security]],
['/network/cgnat-inbound-connections/','CGNAT and Inbound Connections: Why Port Forwarding May Not Work','CGNAT port forwarding','Carrier-grade NAT can place a private/shared address between your router and the public Internet, preventing ordinary inbound forwarding from reaching your LAN.', 'Compare router WAN status with the public address shown by a trusted service, without publishing either value.', ['Read the router WAN address and connection type privately.','Check whether the provider or router identifies CGNAT/shared addressing.','Test local service access separately from Internet access.','Prefer provider-supported public IPv4, IPv6 firewall policy or VPN/relay options.'],[['WAN and public address differ','An upstream translation layer may exist','Ask the provider about the service'],['Local service works','The application and LAN may be fine','Do not open extra ports blindly'],['IPv6 is available','Inbound model may differ','Use an explicit IPv6 firewall policy']], [S.rfc7857,S.cisa], 'Do not expose a service merely to test it. Public IPv4 availability and IPv6 behavior are provider-specific.', [R.security,R.problem]],
['/network/nat-loopback-not-working/','NAT Loopback Not Working: Local Access via a Public Name','NAT loopback hairpin','NAT loopback or hairpin behavior lets a device inside the LAN reach a service through its public name. Not every router supports it.', 'Compare local hostname, local address and public-name behavior without changing port rules first.', ['Confirm the service works on its authorised local address.','Check internal DNS or split-horizon options.','Test the public name from an external authorised connection if appropriate.','Use an internal DNS record or documented router feature when hairpin is absent.'],[['Local address works','Service and LAN path are available','Inspect DNS/hairpin behavior'],['Public name fails only inside','Hairpin may be unsupported','Use split DNS or local name'],['External access fails too','Forwarding or upstream path is separate','Diagnose WAN/CGNAT safely']], [S.rfc7857,S.msDns], 'Hairpin failure is not proof that port forwarding is wrong. Keep public services protected and use VPN where appropriate.', [R.problem,R.security]],
['/network/ipv6-router-advertisement-not-working/','IPv6 Router Advertisement Missing: Check the Default Route','IPv6 router advertisement','IPv6 clients normally learn a default router through Router Advertisements; missing advertisements can leave a device with a link-local address but no usable path.', 'Compare IPv6 address, default route and DNS delivery on the same authorised network.', ['Check whether the client has a global IPv6 address or only link-local.','Inspect the IPv6 default route and router status.','Compare another client and wired/Wi-Fi paths.','Check ISP prefix delegation and router IPv6 mode before disabling IPv6.'],[['Link-local only','The client lacks a usable global path','Check RA and prefix delegation'],['Global address, no route','Default-router information is missing','Inspect router advertisements'],['IPv4 works, IPv6 fails','Dual-stack branch is isolated','Compare ISP/router IPv6 status']], [S.rfc8415,S.msNet], 'IPv6 menu names differ by vendor. Disabling IPv6 can hide rather than fix a provider or router configuration issue.', [R.problem,R.ip]],
['/network/ipv6-prefix-delegation-failed/','IPv6 Prefix Delegation Failed: What the Router Status Means','IPv6 prefix delegation failed','A router may have IPv6 capability but still lack a delegated prefix for its LAN. The WAN status and ISP handoff determine what the router can advertise internally.', 'Use the router’s IPv6 status and provider documentation rather than guessing a prefix size or manual address.', ['Record the IPv6 WAN status and delegation error privately.','Check whether the ISP requires DHCPv6-PD, PPPoE or another handoff.','Confirm the LAN has a delegated prefix before changing RA settings.','Ask the provider if the service supports third-party router delegation.'],[['No delegated prefix','LAN cannot build its normal global subnet','Check WAN handoff/provider'],['WAN IPv6 only','LAN advertisement may be incomplete','Review router IPv6 mode'],['Prefix changes after reboot','Lease or provider policy may vary','Record dates and source details']], [S.rfc8415,S.googleFiber], 'Exact prefix sizes and WAN values are provider-specific and should never be invented from a generic IPv6 guide.', [R.problem,R.security]],
['/network/ethernet-link-speed-100mbps/','Ethernet Stuck at 100 Mbps: Cable, Port or Negotiation?','Ethernet stuck at 100 Mbps','A link that negotiates at 100 Mbps can be limited by cable pairs, port capability, adapter settings, a wall jack or a damaged connector.', 'Check negotiated link speed first; an Internet speed test alone cannot identify the physical bottleneck.', ['Read the negotiated link speed on the client or switch.','Swap one cable and one known-good port.','Compare the same device at another authorised port.','Keep auto-negotiation unless the manufacturer documents another requirement.'],[['Link is 100 Mbps','Physical path or port may limit the link','Swap cable/port systematically'],['Link is 1 Gbps, Internet slow','WAN or service path is separate','Test gateway and ISP path'],['Only one wall jack fails','In-wall termination may be involved','Use a direct cable comparison']], [S.msNet,S.cisa], 'Do not force duplex or speed without documentation; mismatched settings can make the link less stable.', [R.problem,R.tools]],
['/network/ethernet-port-keeps-disconnecting/','Ethernet Port Keeps Disconnecting: Isolate the Physical Layer','Ethernet port disconnecting','Repeated link drops can come from a cable, port, NIC power setting, switch loop or unstable hardware rather than DNS or Wi-Fi.', 'Use a one-variable isolation sequence and note timestamps privately.', ['Check link LEDs and event timestamps.','Replace the cable and use another router/switch port.','Compare with Wi-Fi only as a control, not as a fix.','Review adapter power management and driver documentation.'],[['Only one cable fails','Cable or termination is likely','Replace or test directly'],['One port fails for all devices','Port hardware or configuration','Use another documented port'],['All ports flap','Power, loop or hardware issue','Check topology and router logs']], [S.msNet,S.cisa], 'Avoid uploading logs that contain MAC addresses or hostnames. A reset is not a substitute for a physical isolation test.', [R.problem,R.security]],
['/network/vlan-guest-device-isolation/','Guest VLAN Cannot Reach a Printer or NAS: Understand the Boundary','guest VLAN cannot reach printer','Guest and IoT isolation can intentionally block local discovery and access to printers, NAS devices and management pages.', 'Verify the intended policy before opening cross-network access.', ['Identify the client and service VLANs privately.','Test gateway reachability separately from service reachability.','Check the router/AP isolation policy and firewall direction.','Create only a documented least-privilege exception if needed.'],[['Internet works, printer fails','Isolation may be working as designed','Use approved exception or same VLAN'],['DHCP fails on guest VLAN','Tagging or scope issue may exist','Check router/AP/switch contract'],['Management page reachable','Policy may be too broad','Restrict admin access']], [S.cisa,S.ciscoWifi7], 'VLAN tags and firewall controls are vendor-specific. Do not treat a guest network as identical across products.', [R.security,R.problem]],
['/network/latency-under-load-bufferbloat/','Latency Under Load: Diagnose Bufferbloat Without Guessing','bufferbloat latency under load','A connection can have adequate headline speed but large queueing delay when uploads or downloads fill the bottleneck.', 'Compare idle and loaded latency with a controlled, authorised test and a wired baseline where possible.', ['Measure idle gateway and Internet latency.','Repeat while one controlled upload or download runs.','Compare wired and Wi-Fi results.','Test documented QoS/SQM changes one at a time and recheck.'],[['Idle low, loaded high','Queueing at a bottleneck is plausible','Check upload/download shaping'],['Gateway latency rises','Local Wi-Fi or router queue involved','Test wired and local path'],['Only one device spikes','Client or application load','Check device traffic']], [S.cisa,S.msNet], 'There is no universal good latency threshold. ICMP replies can be deprioritized, so use multiple observations.', [R.tools,R.wifi]],
['/wifi/6ghz-network-not-visible/','Wi-Fi 6E 6 GHz Network Not Visible: Compatibility Checklist','Wi-Fi 6E 6 GHz network not visible','A 6 GHz SSID needs compatible router and client hardware, supported software, allowed regional operation and an appropriate security mode.', 'Check both endpoints and region before changing channels or buying another device.', ['Confirm the router actually supports 6 GHz, not only Wi-Fi 6.','Check the client adapter, OS and driver support.','Verify WPA3/security and region settings from official documentation.','Compare a 5 GHz connection as a control.'],[['Router supports 6E, client does not','The client cannot see 6 GHz','Use 5 GHz or supported client'],['Client supports 6E, SSID absent','Region, firmware or security may block it','Check current vendor guidance'],['SSID appears, connection fails','Authentication/driver issue possible','Update and verify WPA3 support']], [S.appleWifi,S.wifiAlliance], '6 GHz availability and channels vary by country, firmware and device. Do not select a false regulatory region to unlock options.', [R.wifi,R.problem]],
['/wifi/dfs-channel-keeps-changing/','DFS Channel Keeps Changing: Radar Detection Explained','DFS channel keeps changing','DFS channels share spectrum with radar systems; an access point may move channels or pause during checks when radar is detected.', 'Decide whether the extra spectrum is worth the compatibility and availability trade-off.', ['Record the band, channel width and time of the change.','Check whether the selected channel is DFS in your region.','Compare a permitted non-DFS channel.','Retest affected clients and backhaul after the change.'],[['AP changes channel','Radar event or channel availability check','Compare non-DFS option'],['Some clients disappear','Client DFS support may differ','Use a compatible channel'],['Startup takes longer','Channel availability check may occur','Follow vendor behavior']], [S.ciscoDfs,S.appleWifi], 'DFS channel lists and power rules are regional. A wider channel is not automatically a better channel.', [R.wifi,R.problem]],
['/wifi/wpa2-wpa3-transition-mode/','WPA2/WPA3 Transition Mode: Keep Legacy Devices Connected','WPA2 WPA3 transition mode','Transition mode can allow compatible clients to use WPA3 while older WPA2-AES clients remain connected, but compatibility depends on the router and client.', 'Use the strongest documented mode that your device mix supports, without falling back to weak legacy encryption.', ['List affected client types privately.','Check router and client WPA3/PMF support.','Choose WPA3 or transition mode from current documentation.','Reconnect and verify older devices without enabling WEP/TKIP.'],[['New clients connect, old fail','Mode or client compatibility issue','Use transition mode if supported'],['All clients fail','Security/driver settings may be wrong','Check firmware and credentials'],['Only 6 GHz fails','6 GHz security requirement may apply','Verify WPA3 and region']], [S.wifiAlliance,S.appleWifi], 'Changing security mode disconnects clients and may require rejoining. WPA2/WPA3 wording is not identical across vendors.', [R.security,R.wifi]],
['/wifi/wpa3-device-cannot-connect/','Device Cannot Connect to WPA3: Driver and Security Checks','device cannot connect WPA3','A WPA3 failure can come from the adapter, operating system, driver, PMF requirement or router mode—not only from the password.', 'Verify compatibility before weakening the whole network.', ['Confirm the exact client adapter and OS version.','Update the client driver and router firmware from official sources.','Check whether WPA3-Personal and PMF are supported.','Use a separate documented compatibility network only if necessary.'],[['Older adapter','WPA3 may not be supported','Use WPA2-AES or replace adapter'],['Password correct, auth fails','PMF/security mode mismatch','Check router/client support'],['Only one OS fails','Driver or OS support differs','Use the vendor path']], [S.wifiAlliance,S.appleWifi], 'Do not downgrade the main network to WEP, TKIP or open security to accommodate one old device.', [R.security,R.wifi]],
['/wifi/wifi-7-mlo-not-working/','Wi-Fi 7 MLO Not Working: Check Both Ends','Wi-Fi 7 MLO not working','Multi-Link Operation requires compatible AP and client capabilities, firmware, security, bands and regulatory conditions; a Wi-Fi 7 label alone is not enough.', 'Check the negotiated connection and capability evidence before assuming MLO is active.', ['Confirm router and client support compatible MLO modes.','Verify WPA3, firmware and region requirements.','Check whether the client reports one or multiple links.','Compare performance with MLO enabled and disabled using the same location.'],[['Wi-Fi 7 client connects on one link','Fallback may be normal','Check MLO mode and firmware'],['MLO option absent','Hardware or firmware limitation','Use documented support matrix'],['Connection unstable','Band/channel or client issue','Test narrower configuration']], [S.ciscoWifi7,S.appleWifi], 'MLO modes vary. Do not promise a specific throughput or latency gain from the marketing label.', [R.wifi,R.problem]],
['/wifi/802-11k-v-r-roaming/','802.11k/v/r Roaming: What Fast Roaming Actually Changes','802.11k v r roaming','802.11k, 802.11v and 802.11r assist roaming in different ways; the client still makes key decisions and compatibility can vary.', 'Separate roaming protocol support from mesh backhaul, band steering and extender marketing.', ['Confirm the APs share the intended SSID/security design.','Check client support and fast-transition settings.','Test roaming with one known client while moving between APs.','Disable one optional feature at a time if a client fails.'],[['Client refuses association','FT/security compatibility issue','Use a compatible transition setting'],['Roaming is slow','Client or overlap may be involved','Review RF and AP placement'],['Only one device fails','Client-specific behavior','Keep a documented exception']], [S.appleWifi,S.ciscoDfs], 'Roaming behavior is not guaranteed by a checkbox and differs by client, firmware and controller.', [R.wifi,R.problem]],
['/wifi/20mhz-vs-40mhz-5ghz/','20 MHz vs 40 MHz Wi-Fi: Choose Stability or Capacity','20 MHz vs 40 MHz Wi-Fi','Channel width changes how much spectrum a connection uses; wider is not always faster in a crowded home or with legacy clients.', 'Choose width from local interference, client support and stability evidence.', ['Check band and current width in the router status.','Compare a narrower setting with the same client and location.','Watch disconnects and latency, not only link rate.','Respect local channel and DFS rules.'],[['Crowded 2.4 GHz','Wider width may create overlap','Use conservative width'],['Clean 5 GHz','Wider width may add capacity','Verify client support'],['Legacy client fails','Width compatibility issue','Use a supported mode']], [S.appleWifi,S.ciscoDfs], 'Channel width guidance is not a universal best setting. Region and client capabilities matter.', [R.wifi,R.problem]],
['/security/router-firmware-update-failed/','Router Firmware Update Failed: Safe Recovery Before Reset','router firmware update failed','A failed update needs the exact model, hardware revision, power state and vendor recovery procedure; random firmware files can brick a router.', 'Preserve the model and revision evidence and use only the manufacturer or ISP recovery path.', ['Do not power-cycle repeatedly unless the manual says it is safe.','Identify the exact model, revision and current status LEDs.','Open the official recovery/manual page for that exact device.','Use a documented backup or recovery image only when the vendor instructs it.'],[['Router still responds','Update may have rolled back or partially applied','Check version and release notes'],['No management page','Boot/recovery state may be involved','Use official recovery steps'],['ISP-managed hardware','Provider controls firmware','Contact provider before reset']], [S.cisa,S.netRax10], 'Firmware recovery instructions are model-specific. Do not use a generic timing or file for another hardware revision.', [R.reset,R.security]],
['/security/router-cve-vendor-advisory/','Router CVE vs Vendor Advisory: Match the Exact Firmware','router CVE vendor advisory','A CVE record is an index of a vulnerability; the vendor advisory and exact model/firmware determine whether your router is affected and fixed.', 'Record the product, hardware revision, firmware and source dates before deciding urgency.', ['Find the exact model and revision privately.','Open the vendor advisory and compare affected/fixed versions.','Check the NVD or CISA KEV context without treating CVSS as personal risk.','Update, replace or escalate according to the vendor’s remediation.'],[['Model not listed','Do not infer applicability','Check vendor support'],['Affected version listed','A fix or mitigation may exist','Follow advisory steps'],['Unsupported product','Patches may not be available','Plan replacement/provider help']], [S.cisa,{name:'NIST NVD — CVE records',url:'https://nvd.nist.gov/',note:'CVE metadata and vendor references'}], 'A live vulnerability directory requires ongoing maintenance. This page explains the evidence path; it is not a current list of vulnerable models.', [R.security,R.reset]],
['/security/guest-wifi-iot-isolation/','Guest Wi-Fi for IoT: What It Protects and What It Breaks','guest Wi-Fi IoT isolation','Guest Wi-Fi can reduce access from visitors or lower-trust devices to the main LAN, but local printing, casting and hub discovery may stop.', 'Use segmentation deliberately and verify the router’s actual isolation behavior.', ['List which devices need Internet only versus local access.','Check guest-to-LAN and guest-client isolation options.','Use a distinct strong guest password.','Test discovery and management from an authorised client after enabling isolation.'],[['Internet works, LAN fails','Isolation may be intentional','Create a narrow exception or use a hub'],['Guests see each other','Client isolation may be off','Review the guest policy'],['IoT needs local hub','Segmentation design must allow it','Use documented VLAN/firewall rules']], [S.cisa,S.appleWifi], 'Guest Wi-Fi is not identical across routers and is not a replacement for updates, strong device credentials or support lifecycle.', [R.security,R.wifi]],
['/security/upnp-vs-port-forwarding/','UPnP vs Port Forwarding: Automatic and Manual Exposure','UPnP vs port forwarding security','UPnP can let local applications request mappings automatically; port forwarding is a deliberate rule you create. Both need a service, direction and exposure review.', 'Inventory the actual dependency before disabling or leaving automatic mappings enabled.', ['Review current mappings without sharing them publicly.','Identify the device and application requesting each mapping.','Prefer the narrowest documented rule or safer relay/VPN design.','Remove stale mappings and retest the known application.'],[['Automatic mapping','Convenient but less explicit','Review the local device and need'],['Manual rule','Intentional inbound exposure','Restrict source and cleanup date'],['No known need','Extra exposure may be unnecessary','Disable per vendor guidance']], [S.cisa,{name:'IETF RFC 6886 — NAT-PMP',url:'https://datatracker.ietf.org/doc/rfc6886/',note:'automatic port mapping context'}], 'Disabling UPnP may break legitimate apps. NAT is not a complete security boundary and port forwarding should be treated as exposure.', [R.security,R.problem]],
['/security/router-recovery-after-unauthorized-change/','Router Settings Changed by Someone Else: Recovery Checklist','router settings changed unauthorized','An unfamiliar DNS, admin, remote-management or forwarding setting needs evidence-preserving triage, not an immediate assumption of compromise.', 'Secure the management path, use the official recovery route and rebuild only what is needed.', ['Record the changed setting and time privately.','Check whether the router is ISP-managed or shared with another administrator.','Change credentials through the trusted local/vendor path.','Update firmware and review DNS, remote management, WPS, UPnP and forwarding.'],[['One setting differs','Mistake or old automation is possible','Verify account/device access'],['DNS/forwarding changed','Traffic or exposure path changed','Restore documented safe values'],['Cannot regain access','Recovery path is needed','Use vendor/ISP reset guidance']], [S.cisa,S.appleWifi], 'Preserve useful evidence before a reset, but never send secrets to Router Portal. High-consequence incidents may need professional help.', [R.security,R.reset]],
['/device/router-ip-gateway-windows-11/','Find Router IP and Default Gateway on Windows 11','router IP gateway Windows 11','Windows 11 exposes the current network properties and the command line can show the default gateway for the active adapter.', 'Use the connected Wi-Fi or Ethernet adapter, not a disconnected VPN or virtual interface.', ['Open Settings and select Network & internet.','Open the connected Wi-Fi or Ethernet properties.','Find IPv4 Default gateway, or run ipconfig in Command Prompt.','Use the value from the active adapter when opening the local router page.'],[['Multiple adapters','VPN/virtual routes can confuse the result','Match the connected interface'],['No gateway','DHCP or network path may be missing','Diagnose connection first'],['169.254 address','Normal DHCP lease may be absent','Check router/DHCP']], [S.msNet], 'The gateway is network-assigned and may not be 192.168.1.1. Windows menu labels can change with updates.', [R.ip,R.problem]],
['/device/router-ip-gateway-windows-10/','Find Router IP and Default Gateway on Windows 10','router IP gateway Windows 10','Windows 10 shows the default gateway in adapter details and ipconfig remains a practical fallback.', 'Select the adapter currently connected to the router you are authorised to manage.', ['Open Network & Internet settings.','Open the connected adapter properties or Network and Sharing Center.','Run ipconfig /all when the UI is unclear.','Use the Default Gateway field, not the device’s own IPv4 address.'],[['Wi-Fi and Ethernet both active','Each interface can have a different path','Use the intended adapter'],['VPN active','The route may be captured','Compare with authorised VPN off'],['Gateway absent','DHCP/static profile needs review','Check connection settings']], [S.msNet], 'Do not use a popular IP list as proof. Record the Windows version because navigation differs from Windows 11.', [R.ip,R.problem]],
['/device/router-ip-gateway-macos/','Find Router IP and Gateway on macOS','router IP gateway macOS','macOS network details identify the Router field for the connected interface; the displayed private Wi-Fi address is not the gateway.', 'Use System Settings or the route command for the active connection.', ['Open System Settings and choose the connected Wi-Fi or Ethernet service.','Open Details and locate TCP/IP or Router information.','Compare with the default route in Terminal if needed.','Open the local address only from the matching authorised network.'],[['Router field present','This is the local gateway','Use it for local access'],['VPN changes route','A different interface may be active','Compare routes carefully'],['No router value','Network may be isolated or incomplete','Check DHCP/link status']], [{name:'Apple — Connect Mac to the Internet',url:'https://support.apple.com/en-us/101589',note:'Mac network settings'}], 'macOS labels differ by release. Private Wi-Fi address settings are separate from the router field.', [R.ip,R.problem]],
['/device/router-ip-gateway-iphone/','Find Router IP on iPhone Wi-Fi Details','router IP gateway iPhone','iPhone shows the router field inside the details for the currently connected Wi-Fi network.', 'Stay connected to the intended SSID and distinguish Router, IP Address, Subnet Mask and DNS.', ['Open Settings and Wi-Fi.','Tap the connected network’s information button.','Read Router and IPv4/IPv6 fields.','Use the Router value only while connected to that network.'],[{name:'Apple — Recommended Wi-Fi settings',url:'https://support.apple.com/en-us/102766',note:'iPhone Wi-Fi and privacy context'}], 'Cellular data, VPNs and private Wi-Fi addresses do not change the principle: the router field belongs to the connected Wi-Fi network.', [R.ip,R.problem]],
['/device/router-ip-gateway-android/','Find Router IP on Android Wi-Fi Details','router IP gateway Android','Android Wi-Fi details can show gateway, IP and DNS fields, but menu names vary by Android version and manufacturer skin.', 'Use the network details for the currently connected SSID and do not infer the gateway from the phone IP.', ['Open Settings and Network/Internet or Connections.','Tap the connected Wi-Fi network and open its details.','Look for Gateway, Router or advanced IP information.','If the field is hidden, use the router status or another authorised device.'],[{name:'Google Android Help — Connect to Wi-Fi',url:'https://support.google.com/android/answer/9654714?hl=en-GB',note:'Android network settings'}], 'Android OEM menus are not stable enough for one universal click path. Verify the device version before publishing a screenshot.', [R.ip,R.problem]],
['/device/router-ip-gateway-linux-command-line/','Find Router Gateway with ip route on Linux','router gateway ip route Linux','On Linux, the default route normally shows the gateway after default via, but VPNs, containers and multiple interfaces can add other routes.', 'Read the route associated with the intended interface instead of copying a popular private IP.', ['Open a terminal.','Run ip route and identify the default route.','Check the interface name and metric.','Compare IPv4 and IPv6 routes when dual-stack behavior matters.'],[{name:'ip-route manual — Linux man-pages',url:'https://man7.org/linux/man-pages/man8/ip-route.8.html',note:'route selection and default route'}], 'A route is not automatically a router-admin address; it is the next hop for that path. Containers and VPNs can change the view.', [R.ip,R.problem]],
['/device/router-ip-gateway-chromebook/','Find Router IP on Chromebook Network Details','router IP gateway Chromebook','ChromeOS network settings provide the active Wi-Fi connection details, while managed devices and version channels can limit what is visible.', 'Use the active network and do not assume a Chromebook uses a familiar home gateway.', ['Open the Chromebook settings.','Select Network and the connected Wi-Fi.','Review IP and gateway details if shown.','Use the router or another authorised device when ChromeOS hides advanced fields.'],[{name:'Google Chromebook Help — Connect to Wi-Fi',url:'https://support.google.com/chromebook/answer/1047420?hl=en',note:'ChromeOS network workflow'}], 'ChromeOS menus change with channel and administration policy. Linux-container routes are not necessarily the home router route.', [R.ip,R.problem]],
['/device/router-ip-gateway-playstation/','Find Network Gateway on PlayStation','router IP gateway PS5 PS4','PlayStation network status shows connection details and NAT context, while manual IP entry is a separate advanced action.', 'Use automatic settings unless the network administrator has documented a static configuration.', ['Open the console network settings and view connection status.','Read the current IP and gateway fields if exposed.','Run the connection test and note NAT type separately.','Use DHCP reservation on the router rather than guessing a console address.'],[{name:'PlayStation Support — Connect to the Internet',url:'https://www.playstation.com/en-us/support/connectivity/internet-connect-playstation/',note:'console connectivity workflow'}], 'Console menus differ by generation and firmware. NAT type does not itself reveal the router’s admin address.', [R.ip,R.problem]],
['/device/router-ip-gateway-xbox/','Find IP and Gateway on Xbox Network Settings','router IP gateway Xbox','Xbox advanced network settings can show IP, subnet, gateway and DNS fields, with NAT status as a separate diagnostic.', 'Keep automatic/DHCP settings unless a documented reservation or static design is required.', ['Open Settings and Network settings.','View advanced network settings.','Read Gateway and IP fields for the active connection.','Run the network/NAT test and compare with another authorised device.'],[{name:'Xbox Support — Advanced network settings',url:'https://support.xbox.com/en-US/help/hardware-network/connect-network/advanced-network-settings',note:'Xbox network fields and NAT'}], 'An Xbox gateway is assigned by the network. Avoid manual values copied from another console or router.', [R.ip,R.problem]],
['/device/router-ip-gateway-nintendo-switch/','Find or Enter Network Gateway on Nintendo Switch','router IP gateway Nintendo Switch','Nintendo Switch network settings distinguish automatic configuration from manual IP entry and may show connection-test details.', 'Use automatic configuration first and reserve a stable address on the router when appropriate.', ['Open Internet settings and choose the current network.','Run the connection test to view the network result.','Use manual settings only with documented values.','Avoid changing DNS, IP or gateway together when troubleshooting.'],[{name:'Nintendo Support — Manual IP settings',url:'https://en-americas-support.nintendo.com/app/answers/detail/a_id/22412/',note:'Switch network configuration'}], 'Switch generation and firmware affect menu wording. A manually entered gateway must belong to the connected LAN.', [R.ip,R.problem]],
['/device/router-ip-gateway-smart-tv/','Find Router IP on a Smart TV Network Status Screen','router IP gateway smart TV','Smart TVs usually show IP, subnet, gateway and DNS in Network Status, but the path varies by platform, model year and wired/Wi-Fi connection.', 'Use DHCP first and only enter manual settings from the network administrator’s documented plan.', ['Open the TV Network or Connection Status screen.','Identify whether the TV uses Ethernet or Wi-Fi.','Read Gateway and DNS fields without sharing them publicly.','Use a DHCP reservation for stability instead of a random static value.'],[{name:'Samsung Support — TV network troubleshooting',url:'https://www.samsung.com/us/support/troubleshoot/TSG10002209/',note:'TV network status context'}], 'A TV’s IP is not its router gateway. Menu paths require model and firmware verification.', [R.ip,R.problem]],
['/isp/xfinity-bridge-mode/','Xfinity Gateway Bridge Mode: What Changes','Xfinity gateway bridge mode','Xfinity bridge mode changes which device performs routing and can affect gateway Wi-Fi and connected features.', 'Read the current provider instructions and plan the downstream router before enabling the mode.', ['Confirm the gateway model and service features.','Back up or record the current topology privately.','Connect the downstream router according to provider instructions.','Verify WAN address, Wi-Fi behavior and recovery path after the change.'], [S.xfinity], 'Provider UI and feature limits can change. Bridge mode is not the same as access-point mode and may disable gateway features.', [R.login,R.security]],
['/isp/cox-panoramic-bridge-mode/','Cox Panoramic Gateway Bridge Mode: Limits and Recovery','Cox Panoramic bridge mode','Cox documents bridge mode as a provider-specific gateway feature with its own recovery and service implications.', 'Use the Cox model-specific support path and check what Wi-Fi/extender features are affected.', ['Identify the Panoramic gateway model.','Read current Cox bridge instructions before changing the mode.','Connect and configure the personal router on the documented port.','Test Internet, voice/TV/extender dependencies and restore routing if needed.'], [S.cox], 'Do not generalize Cox behavior to another ISP or gateway. Provider-managed features may not survive bridge mode.', [R.login,R.security]],
['/isp/t-mobile-5g-home-gateway-setup/','T-Mobile 5G Home Gateway Setup: App, SIM and Signal','T-Mobile 5G Home gateway setup','Fixed-wireless gateway setup depends on the provider app/account, device generation, SIM/eSIM state, signal placement and firmware.', 'Follow T-Mobile’s current activation and placement flow instead of searching for a universal router IP.', ['Use the provider account/app and identify the gateway generation.','Complete activation and check SIM/service status.','Place the gateway where the provider’s signal guidance supports it.','Verify LAN port, Wi-Fi and app management after activation.'], [S.tmobile], 'Cellular signal and service availability are not determined by a private IP or a generic band list.', [R.login,R.problem]],
['/isp/telstra-modem-settings/','Telstra Modem Settings: Find the Correct Management Path','Telstra modem settings','Telstra modem access depends on the supplied modem model, local connection and current provider documentation.', 'Identify the exact Telstra hardware before using a hostname, address or app workflow.', ['Read the modem model and firmware label privately.','Open Telstra’s current support page for that model.','Connect to the modem’s authorised LAN/Wi-Fi network.','Use the documented recovery and credential path; do not guess defaults.'], [S.telstra], 'ISP hardware can have restricted menus and provider-specific firmware. A retail-router guide may not apply.', [R.login,R.ip]],
['/isp/google-fiber-ont-router/','Google Fiber ONT and Personal Router: Understand the Handoff','Google Fiber ONT personal router','A fiber ONT and a router perform different roles; whether a personal router can replace or sit behind provider equipment depends on the service architecture.', 'Map the Ethernet handoff and provider-supported mode before changing cables or VLAN settings.', ['Identify the ONT, provider router and Ethernet handoff.','Check Google Fiber’s current own-router requirements.','Confirm WAN method and IPv6/TV/voice dependencies from official sources.','Test service recovery before removing provider equipment.'], [S.googleFiber], 'Do not infer PPPoE, VLAN IDs or a usable admin address from the presence of fiber. Provider handoffs vary.', [R.login,R.problem]],
['/isp/isp-gateway-bridge-vs-ap-mode/','Bridge Mode vs Access Point Mode on an ISP Gateway','ISP gateway bridge vs AP mode','Bridge mode usually moves routing upstream or downstream, while access-point mode keeps another device responsible for routing and uses the gateway as a LAN bridge.', 'Choose the mode based on ownership, provider features, IPv6, voice/TV and support—not only double NAT.', ['Draw the current WAN-to-LAN topology.','List which device should provide DHCP, NAT, Wi-Fi and firewall.','Check the ISP’s supported bridge/IP-passthrough/AP behavior.','Change one mode at a time and verify recovery.'], [S.xfinity,S.cox,S.googleFiber], 'The labels are not interchangeable. Exact feature loss and port behavior are provider/model-specific.', [R.security,R.problem]],
['/isp/fixed-wireless-gateway-placement/','5G Home Gateway Placement: Signal Without Guessing Speed','5G home gateway placement','Placement affects cellular signal and can change service quality, but a manufacturer or carrier coverage claim is not a guarantee of speed in a room.', 'Use the provider app/status indicators and compare positions systematically.', ['Record the gateway status at one location.','Move it one variable at a time using provider placement guidance.','Wait for the gateway to settle before comparing.','Check wired and Wi-Fi performance separately.'], [S.tmobile], 'Signal bars, speed tests and coverage claims are different measurements. Avoid moving a device to an unsafe or prohibited location.', [R.problem,R.wifi]],
['/isp/fiber-ont-personal-router/','Fiber ONT to Personal Router: What to Confirm First','fiber ONT personal router setup','Replacing or adding a router behind an ONT requires the provider’s supported WAN handoff, authentication, IPv6 and service-feature details.', 'Collect the current provider documentation before entering any WAN value.', ['Identify ONT and provider service type.','Check whether the handoff is DHCP/IPoE, PPPoE or another documented method.','Confirm voice/TV and support dependencies.','Test rollback before disconnecting the existing equipment.'], [S.googleFiber,S.rfc8415], 'Never invent PPPoE credentials, VLAN IDs or prefix sizes. Use the provider’s current guide or support channel.', [R.login,R.problem]],
['/models/tp-link-deco-x55/','TP-Link Deco X55: Setup, Ports and Router/AP Mode','TP-Link Deco X55 setup','Deco X55 setup and behavior depend on the exact model, hardware revision, pack and whether the system runs as router or access point.', 'Use TP-Link’s current support/download page and the Deco app for the matching hardware.', ['Confirm the X55 model and hardware revision.','Set up the main unit and add nodes through the documented app flow.','Choose router or AP mode based on the upstream topology.','Test wired backhaul, guest network and firmware update behavior.'], [S.tpX55], 'Coverage and device-count figures are manufacturer claims; walls, client radios and placement change real results.', [R.wifi,R.problem]],
['/models/netgear-nighthawk-rax10/','NETGEAR RAX10: Manual, Ports and Firmware Path','NETGEAR RAX10 setup','The RAX10 page should answer exact-model questions about ports, setup, admin access, firmware and reset—not repeat generic router login text.', 'Match the RAX10 manual and support page to the hardware/region before changing settings.', ['Confirm the model label says RAX10.','Use the official installation/manual path.','Identify WAN/LAN ports and indicator meanings.','Check firmware release notes and recovery instructions before updating.'], [S.netRax10], 'AX1800 and feature claims are model specifications, not guaranteed Internet speed. Firmware UI can change.', [R.login,R.security]],
['/models/asus-rt-ax86u-pro/','ASUS RT-AX86U Pro: Variant-Safe Setup and AiMesh Checks','ASUS RT-AX86U Pro setup','RT-AX86U, RT-AX86U Pro and RT-AX86S are closely named variants; port, firmware and feature details must match the suffix.', 'Use the ASUS support page for the exact model and firmware branch.', ['Read the full suffix and hardware/region label.','Open the matching ASUS manual and firmware page.','Check AiMesh role and operating-mode compatibility.','Record original settings before enabling gaming, VPN or QoS features.'], [S.asusAx86], 'Do not transfer a menu or firmware file between variants. Marketing feature names do not establish identical behavior.', [R.login,R.security]],
['/models/linksys-atlas-pro-6-mx5500/','Linksys Atlas Pro 6 MX5500: Node and Backhaul Guide','Linksys Atlas Pro 6 MX5500 setup','The MX5500 guide should cover node onboarding, wired backhaul, app/web management and firmware for this exact mesh family.', 'Match the model and hardware version to Linksys support before pairing nodes.', ['Confirm MX5500/Atlas Pro 6 identity.','Add the parent and nodes through the supported app flow.','Test Ethernet backhaul separately from wireless backhaul.','Review firmware/recovery instructions before resetting a node.'], [S.linksys], 'Mesh coverage and node behavior depend on placement, firmware and client support. Do not generalize to every Velop model.', [R.wifi,R.problem]],
['/models/eero-6-plus-gateway-extender/','eero 6+ Gateway vs Extender: Ports and Compatibility','eero 6 Plus gateway extender','eero 6+ gateway and extender roles are not interchangeable; the gateway has the WAN/LAN handoff while an extender’s ports and role differ.', 'Identify the exact eero unit before planning a replacement or Ethernet backhaul.', ['Read the device label and role in the eero app.','Confirm which unit connects to the upstream modem/ONT.','Check Ethernet port behavior and supported topology.','Use the app’s setup and update flow for the existing eero network.'], [S.eero], 'Coverage, device count and feature claims depend on the whole eero system and service topology.', [R.wifi,R.problem]],
['/models/netgear-nighthawk-m6-mr6150/','NETGEAR Nighthawk M6 MR6150: Bands, SIM and Ethernet','NETGEAR Nighthawk M6 MR6150 setup','MR6150 setup depends on the exact carrier/region, SIM/APN, supported bands, firmware and whether it is used as travel or home failover Internet.', 'Use the matching NETGEAR support page and carrier requirements rather than a generic 5G claim.', ['Confirm MR6150 and carrier/region.','Install the SIM and follow the official activation/APN path.','Check Wi-Fi, Ethernet and external-antenna ports from the manual.','Test battery, tethering and bridge/failover behavior only where documented.'], [{name:'NETGEAR — Nighthawk M6 MR6150',url:'https://www.netgear.com/mobile-wifi/hotspots/mr6150/',note:'product and regional context'}], 'A supported band list does not guarantee carrier service. Plan, certification, signal and firmware all matter.', [R.problem,R.security]],
['/models/inseego-mifi-x-pro-5g/','Inseego MiFi X PRO 5G: Identify the Correct Variant','Inseego MiFi X PRO 5G setup','MiFi X PRO variants such as M3000/M3100/M3200 can differ by carrier and region, so the model code must be matched before using a manual or firmware file.', 'Use Inseego’s exact user guide and carrier documentation for the device variant.', ['Read the model code and carrier label.','Check the matching bands, SIM, Wi-Fi and Ethernet details.','Use the official screen/app setup path.','Review firmware and battery guidance from the matching guide.'], [{name:'Inseego — MiFi X PRO documentation',url:'https://inseego.com/resources/product-documentation/mifi-x-pro/user-guide/',note:'variant-specific manual'}], 'Do not infer service from branding or a generic band table. Carrier certification and APN requirements can differ.', [R.problem,R.security]],
['/models/teltonika-rutx50/','Teltonika RUTX50: Dual-SIM, RutOS and Recovery','Teltonika RUTX50 setup','RUTX50 is an industrial 5G gateway with dual-SIM/eSIM, Ethernet, RutOS and model-specific recovery/environment details.', 'Use Teltonika’s manual and product page for the exact hardware and regional cellular support.', ['Confirm the RUTX50 hardware and cellular region.','Review SIM/eSIM and failover configuration.','Map Ethernet, Wi-Fi, GPS and antenna connections.','Use RutOS firmware/recovery instructions and keep a private configuration backup.'], [{name:'Teltonika — RUTX50 manual',url:'https://wiki.teltonika-networks.com/view/RUTX50_Manual',note:'official manual'}], 'Industrial features and cellular bands are not a guarantee of carrier service or performance. Mounting and power requirements matter.', [R.security,R.problem]],
['/models/arris-surfboard-g34/','ARRIS SURFboard G34: DOCSIS, Activation and Wi-Fi Limits','ARRIS SURFboard G34 setup','The G34 is a cable modem-router combination whose activation, ISP approval, DOCSIS service and Wi-Fi features must be checked together.', 'Match the cable provider’s current approval list and the exact G34 documentation.', ['Confirm the G34 model and ISP/service tier.','Check provider activation and DOCSIS compatibility.','Read modem registration lights separately from Wi-Fi status.','Use SURFboard support for firmware, reset and router settings.'], [{name:'SURFboard — G34 product page',url:'https://www.surfboard.com/products/wi-fi-cable-modems/g34/',note:'model specifications and support'}], 'Provider approval is regional and plan-dependent. Do not promise service from the hardware name alone.', [R.problem,R.login]],
['/models/netgear-nighthawk-cax30/','NETGEAR CAX30: Cable Activation and Bridge Considerations','NETGEAR CAX30 setup','CAX30 setup combines DOCSIS registration, provider approval, Wi-Fi router settings and any supported bridge arrangement.', 'Use NETGEAR’s manual and the cable provider’s current qualification list.', ['Confirm CAX30/CAX30S and region.','Complete provider activation before diagnosing Wi-Fi.','Read cable status lights and router status separately.','Check firmware, reset and bridge/router documentation before topology changes.'], [{name:'NETGEAR — CAX30 support',url:'https://www.netgear.com/support/product/cax30',note:'model manual and support'}], 'Cable service, voice features and bridge behavior vary by provider. Do not reuse instructions from another DOCSIS combo.', [R.problem,R.login]]
];
export function makePilotPages(pageUrl){
  const selected = [
    ...raw.filter(x=>x[0].startsWith('/network/') || x[0].startsWith('/wifi/') || x[0].startsWith('/security/')).slice(0,24),
    ...raw.filter(x=>x[0].startsWith('/device/')).slice(0,8),
    ...raw.filter(x=>x[0].startsWith('/isp/')).slice(0,8),
    ...raw.filter(x=>x[0].startsWith('/models/')).slice(0,10)
  ];
  return selected.map((x)=>{
    const [slug,title,keyword,answer,coverage,steps] = x;
    const short = x.length === 9;
    const rows = short ? [['Exact scope','The page is limited to the named model, platform or provider','Match the current official source'],['UI or firmware','Menus and behavior can change','Check the exact version or revision'],['Unknown detail','No safe universal claim is made','Use the official support path']] : x[6];
    const sources = short ? x[6] : x[7];
    const limits = short ? x[7] : x[8];
    const related = short ? x[8] : x[9];
    return {slug,title:`${title} | Router Portal`,description:`${answer} Safe steps, source notes and model or network limits included.`,label:'Pilot research guide',h1:title,searchTerms:`${keyword}, router guide, troubleshooting, ${slug.split('/').filter(Boolean).join(', ')}`,schemaType:'Article',intro:answer,body:makeBody({answer,coverage,steps,rows,sources:Array.isArray(sources)?sources:[sources],limits,related:Array.isArray(related)?related:[related]},pageUrl)};
  });
}

